---@type fun(text: string): any
fe.json.decode = nil

--- Serialize a value (tables, strings, numbers, booleans); integer keys of non-sequence tables are written "#k".
---@type fun(value: any, pretty?: boolean): string
fe.json.encode = nil

--- Read and parse a JSON file inside the game folder ('@fe/' for builtin).
