--- Load and manage worlds (maps). Several can be loaded at once.
fe.world = fe.world or {}

--- Load maps/<map>/map.json as a world called `name` (replacing one of that name).
---@type fun(name: string, map: string): World
fe.world.load = nil

--- A loaded world by name.
---@type fun(name: string): World?
fe.world.get = nil

--- Unload a world.
---@type fun(name: string)
fe.world.unload = nil

--- Names of loaded worlds.
---@type fun(): string[]
fe.world.list = nil

--- Start loading maps/<map>/map.json in the background: the map file is parsed and the models, images and sprites it names are decoded on worker threads. Returns a ticket for load_progress and finish_load.
---@type fun(name: string, map: string): integer
fe.world.load_async = nil

--- Background load progress 0..1; 1 when finish_load won't wait (or the load failed).
---@type fun(ticket: integer): number
fe.world.load_progress = nil

--- Create the world from a background load, replacing a world of that name. Before progress reaches 1 it waits for the map file and leaves undecoded assets to load on first use. Raises the load's error (a missing or invalid map). The ticket is used up.
---@type fun(ticket: integer): World
fe.world.finish_load = nil

--- Drop a background load that will not be finished (a cancelled warp): the ticket stops advancing and becomes unknown; a worker still parsing the map finishes in the background and its result is discarded, and assets already decoded stay in the cache like any other.
---@type fun(ticket: integer)
fe.world.cancel_load = nil

